171:         rank.addItem(and2);
172: 
173:         a.setConnectivity(b, 0.1);
174:         b.setConnectivity(c, 0.2);
175:         c.setConnectivity(d, 0.3);
176:         d.setConnectivity(e, 0.4);
177:         e.setConnectivity(f, 0.5);
178:         f.setConnectivity(g, 0.6);
