184:         RankItem rankClone = (RankItem) qClone.getModel().getQueryTree().getRoot();
185:         AndItem and1Clone = (AndItem) rankClone.getItem(0);
186:         AndItem and2Clone = (AndItem) rankClone.getItem(1);
187:         OrItem orClone = (OrItem) and1Clone.getItem(2);
188: 
189:         WordItem aClone = (WordItem) and1Clone.getItem(0);
