191:         WordItem cClone = (WordItem) orClone.getItem(0);
192:         WordItem dClone = (WordItem) orClone.getItem(1);
193:         WordItem eClone = (WordItem) and1Clone.getItem(3);
194:         WordItem fClone = (WordItem) and2Clone.getItem(0);
195:         WordItem gClone = (WordItem) and2Clone.getItem(1);
196: 
197:         assertNotSame(rankClone, rank);
198:         assertNotSame(and1Clone, and1);
199:         assertNotSame(and2Clone, and2);
200:         assertNotSame(orClone, or);
201: 
202:         assertNotSame(aClone, a);
203:         assertNotSame(bClone, b);
204:         assertNotSame(cClone, c);
205:         assertNotSame(dClone, d);
206:         assertNotSame(eClone, e);
207:         assertNotSame(fClone, f);
208:         assertNotSame(gClone, g);
209: 
210:         assertEquals(aClone.getConnectedItem(), bClone);
211:         assertEquals(bClone.getConnectedItem(), cClone);
212:         assertEquals(cClone.getConnectedItem(), dClone);
213:         assertEquals(dClone.getConnectedItem(), eClone);
214:         assertEquals(eClone.getConnectedItem(), fClone);
215:         assertEquals(fClone.getConnectedItem(), gClone);
216: 
217:         double delta = 0.0000001;
218:         assertEquals(0.1, aClone.getConnectivity(), delta);
219:         assertEquals(0.2, bClone.getConnectivity(), delta);
220:         assertEquals(0.3, cClone.getConnectivity(), delta);
