171:     @Override
172:     public Object get(CompoundName key,
173:                       Map<String, String> context,
174:                       com.yahoo.processing.request.Properties substitution) {
175:         GetterSetter propertyAccessor = propertyAccessors.get(key);
176:         if (propertyAccessor != null && propertyAccessor.getter != null) return propertyAccessor.getter.get(query);
177: 
178:         if (key.first().equals(Ranking.RANKING)) {
179:             Ranking ranking = query.getRanking();
180:             if (key.size() > 2) {
181:                 // pass the portion after "ranking.features/properties" down
182:                 if (key.get(1).equals(Ranking.FEATURES)) return ranking.getFeatures().getObject(key.rest().rest().toString());
183:                 if (key.get(1).equals(Ranking.PROPERTIES)) return ranking.getProperties().get(key.rest().rest().toString());
184:             }
185:         }
186: 
187:         return super.get(key, context, substitution);
188:     }
189: 
190:     private void setInternal(CompoundName key, Object value, Map<String,String> context) {
191:         GetterSetter propertyAccessor = propertyAccessors.get(key);
192:         if (propertyAccessor != null && propertyAccessor.setter != null) {
193:             propertyAccessor.setter.set(query, value);
194:             return;
195:         }
196: 
197:         if (key.first().equals(Ranking.RANKING)) {
198:             if (key.size() > 2) {
199:                 String restKey = key.rest().rest().toString();
200:                 chained().requireSettable(key, value, context);
201:                 if (key.get(1).equals(Ranking.FEATURES)) {
202:                     setRankFeature(query, restKey, toSpecifiedType(restKey, value,
203:                             profileRegistry.getTypeRegistry().getComponent("features"),
204:                             context));
205:                     return;
206:                 } else if (key.get(1).equals(Ranking.PROPERTIES)) {
207:                     Ranking ranking = query.getRanking();
208:                     ranking.getProperties().put(restKey, toSpecifiedType(restKey, value,
209:                             profileRegistry.getTypeRegistry().getComponent("properties"),
210:                             context));
211:                     return;
212:                 }
213:             }
214:         }
215:         if (reservedPrefix.contains(key.first())) {
216:             // Setting a property under the reserved paths are illegal, while retrieving(get) one is not.
217:             throwIllegalParameter(key.rest().toString(), key.first());
218:         } else {
219:             super.set(key, value, context);
220:         }
221:     }
222: 
223:     @Override
224:     public void set(CompoundName key, Object value, Map<String,String> context) {
225:         // Note: The defaults here are never used
226:         try {
227:             setInternal(key, value, context);
228:         }
229:         catch (Exception e) { // Make sure error messages are informative. This should be moved out of this properties implementation
230:             if (e.getMessage() != null && e.getMessage().startsWith("Could not set"))
231:                 throw e;
232:             else
233:                 throw new IllegalInputException("Could not set '" + key + "' to '" + value + "'", e);
234:         }
235:     }
