237:     @Override
238:     public Map<String, Object> listProperties(CompoundName prefix, Map<String, String> context,
239:                                               com.yahoo.processing.request.Properties substitution) {
240:         Map<String, Object> properties = super.listProperties(prefix, context, substitution);
241:         for (CompoundName queryProperty : Query.nativeProperties) {
242:             if (queryProperty.hasPrefix(prefix)) {
243:                 Object value = this.get(queryProperty, context, substitution);
244:                 if (value != null)
245:                     properties.put(queryProperty.toString(), value);
246:             }
247:         }
248:         return properties;
249:     }
