445:   private static ExecutorResource buildExecutorService(
446:       final CamundaClientConfiguration configuration) {
447:     if (configuration.jobWorkerExecutor() != null) {
448:       return new ExecutorResource(
449:           configuration.jobWorkerExecutor(), configuration.ownsJobWorkerExecutor());
450:     }
451: 
452:     final int threadCount = configuration.getNumJobWorkerExecutionThreads();
453:     final ScheduledExecutorService executor = Executors.newScheduledThreadPool(threadCount);
454:     return new ExecutorResource(executor, true);
455:   }
