472:   @Override
473:   public void close() {
474:     closeables.forEach(
475:         c -> {
476:           try {
477:             c.close();
478:           } catch (final IOException e) {
479:             // ignore
480:           }
481:         });
482: 
483:     executorResource.close();
484:     channel.shutdownNow();
485: 
486:     try {
487:       if (!channel.awaitTermination(15, TimeUnit.SECONDS)) {
488:         throw new ClientException(
489:             "Timed out awaiting termination of in-flight request channel after 15 seconds");
490:       }
491:     } catch (final InterruptedException e) {
492:       throw new ClientException(
493:           "Unexpectedly interrupted awaiting termination of in-flight request channel", e);
494:     }
495: 
496:     try {
497:       httpClient.close();
498:     } catch (final Exception e) {
499:       throw new ClientException("Failed closing http client.", e);
500:     }
501:   }
