334:     asyncStub = gatewayStub;
335:     this.executorResource = executorResource;
336:     this.httpClient = httpClient;
337: 
338:     if (config.getCredentialsProvider() != null) {
339:       credentialsProvider = config.getCredentialsProvider();
340:     } else {
341:       credentialsProvider = new NoopCredentialsProvider();
342:     }
343:     jobClient = newJobClient();
344:     this.httpClient.start();
345:   }
