351:   public static ManagedChannel buildChannel(final CamundaClientConfiguration config) {
352:     final URI address;
353:     address = config.getGrpcAddress();
354: 
355:     final NettyChannelBuilder channelBuilder =
356:         NettyChannelBuilder.forAddress(address.getHost(), address.getPort());
357: 
358:     configureConnectionSecurity(config, channelBuilder);
359:     channelBuilder.keepAliveTime(config.getKeepAlive().toMillis(), TimeUnit.MILLISECONDS);
360:     channelBuilder.userAgent("camunda-client-java/" + VersionUtil.getVersion());
361:     channelBuilder.maxInboundMessageSize(config.getMaxMessageSize());
362:     channelBuilder.maxInboundMetadataSize(config.getMaxMetadataSize());
363: 
364:     if (config.useDefaultRetryPolicy()) {
365:       final Map<String, Object> serviceConfig = defaultServiceConfig();
366:       if (!serviceConfig.isEmpty()) {
367:         channelBuilder.defaultServiceConfig(serviceConfig);
368:         channelBuilder.enableRetry();
369:       }
370:     }
371: 
372:     return channelBuilder.build();
373:   }
374: 
375:   private static CallCredentials buildCallCredentials(final CamundaClientConfiguration config) {
376:     final CredentialsProvider customCredentialsProvider = config.getCredentialsProvider();
377: 
378:     if (customCredentialsProvider == null) {
379:       return null;
380:     }
381: 
382:     return new CamundaCallCredentials(customCredentialsProvider);
383:   }
384: 
385:   private static void configureConnectionSecurity(
386:       final CamundaClientConfiguration config, final NettyChannelBuilder channelBuilder) {
387:     if (!config.isPlaintextConnectionEnabled()) {
388:       final String certificatePath = config.getCaCertificatePath();
389:       SslContext sslContext = null;
390: 
391:       if (certificatePath != null) {
392:         if (certificatePath.isEmpty()) {
393:           throw new IllegalArgumentException(
394:               "Expected valid certificate path but found empty path instead.");
395:         }
396: 
397:         try (final FileInputStream certInputStream = new FileInputStream(certificatePath)) {
398:           sslContext = GrpcSslContexts.forClient().trustManager(certInputStream).build();
399:         } catch (final IOException e) {
400:           throw new RuntimeException(e);
401:         }
402:       }
403: 
404:       channelBuilder.useTransportSecurity().sslContext(sslContext);
405:       if (config.getOverrideAuthority() != null) {
406:         channelBuilder.overrideAuthority(config.getOverrideAuthority());
407:       }
408:     } else {
409:       channelBuilder.usePlaintext();
410:     }
411:   }
